#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 1000

typedef struct {
    int priority;
    int idx;
} E;

typedef struct ListNode {
    E *ele;
    struct ListNode *next;
} ListNode;

typedef struct {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void addLast_LinkedList(LinkedList *link, int priority, int idx) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));

    E *e = (E *) malloc(sizeof(E));
    e->priority = priority;
    e->idx = idx;

    node->ele = e;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}

E *removeFirst_LinkedList(LinkedList *link) {
    if (link->size == 0) exit(-1);

    ListNode *removed = link->head;

    if (link->size == 1) {
        link->head = NULL;
        link->tail = NULL;
    } else {
        link->head = link->head->next;
    }

    link->size--;

    E *ele = (E *) malloc(sizeof(E));
    ele->priority = removed->ele->priority;
    ele->idx = removed->ele->idx;

    free(removed);

    return ele;
}

int cmp(const void *a, const void *b) {
    return *((int *) a) - *((int *) b);
}

int main() {
    int priority[MAX_SIZE];
    int priority_size = 0;

    while (scanf("%d", &priority[priority_size++])) {
        if (getchar() != ',') break;
    }

    LinkedList *link = new_LinkedList();
    for (int i = 0; i < priority_size; i++) {
        addLast_LinkedList(link, priority[i], i);
    }

    qsort(priority, priority_size, sizeof(int), cmp);

    int maxI = priority_size - 1;

    int *ans = (int *) calloc(priority_size, sizeof(int));

    int printIdx = 0;
    while (link->size > 0) {
        E *e = removeFirst_LinkedList(link);

        int p = e->priority;
        int i = e->idx;

        if (p == priority[maxI]) {
            ans[i] = printIdx;
            printIdx++;
            maxI--;
        } else {
            addLast_LinkedList(link, p, i);
        }
    }

    char res[10000];
    for(int i=0; i<priority_size; i++) {
        char tmp[100];
        sprintf(tmp, "%d", ans[i]);

        strcat(res, tmp);
        strcat(res, ",");
    }

    res[strlen(res) - 1] = '\0';

    puts(res);

    return 0;
}
